# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor tensor_matmul3d_cuda(torch::Tensor A, torch::Tensor B);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("tensor_matmul3d_cuda", &tensor_matmul3d_cuda, "3D tensor x matrix matmul (CUDA)");
}
# <<<END_IMPROVE>>>
"""

