# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublas_v2.h>

torch::Tensor tensor_matmul3d_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 3, "A must be 3D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");

    A = A.contiguous();
    B = B.contiguous();

    const int64_t N = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    const int64_t L = B.size(1);

    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(2)");

    auto A2 = A.view({N * M, K});
    auto C = torch::empty({N * M, L}, A.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    cublasSetStream(handle, at::cuda::getCurrentCUDAStream());

    // cuBLAS is column-major. We want C = A2 @ B (row-major).
    // In column-major terms: C^T = B^T @ A2^T
    // So we call cublasSgemm(handle, CUBLAS_OP_N, CUBLAS_OP_N, L, N*M, K, ...)
    // with B as the first matrix (L x K in col-major = K x L in row-major)
    // and A2 as the second matrix (K x N*M in col-major = N*M x K in row-major)
    const float alpha = 1.0f;
    const float beta = 0.0f;

    cublasStatus_t status = cublasSgemm(
        handle,
        CUBLAS_OP_N,   // B is not transposed (col-major: L x K)
        CUBLAS_OP_N,   // A2 is not transposed (col-major: K x N*M)
        (int)L,        // m: rows of op(B) and C in col-major
        (int)(N * M),  // n: cols of op(A2) and C in col-major
        (int)K,        // k: cols of op(B) and rows of op(A2)
        &alpha,
        B.data_ptr<float>(),   // B: col-major L x K, ldb = L
        (int)L,
        A2.data_ptr<float>(),  // A2: col-major K x N*M, lda = K
        (int)K,
        &beta,
        C.data_ptr<float>(),   // C: col-major L x N*M, ldc = L
        (int)L
    );

    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasSgemm failed");

    return C.view({N, M, L});
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
