#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cublasLt.h>

torch::Tensor tensor_matmul3d_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 3, "A must be 3D");
    TORCH_CHECK(B.dim() == 2, "B must be 2D");

    A = A.contiguous();
    B = B.contiguous();

    const int64_t N = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    const int64_t L = B.size(1);

    TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(2)");

    // Flatten A to (N*M, K)
    auto A2 = A.view({N * M, K});
    auto C  = torch::empty({N * M, L}, A.options());

    cublasLtHandle_t ltHandle;
    cublasLtCreate(&ltHandle);

    cublasLtMatmulDesc_t   opDesc   = nullptr;
    cublasLtMatrixLayout_t layoutA  = nullptr;
    cublasLtMatrixLayout_t layoutB  = nullptr;
    cublasLtMatrixLayout_t layoutC  = nullptr;
    cublasLtMatmulPreference_t pref = nullptr;

    bool use_lt = false;

    do {
        if (cublasLtMatmulDescCreate(&opDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F) != CUBLAS_STATUS_SUCCESS) break;

        // We compute C = A2 @ B  (row-major)
        // cuBLASLt row-major: set CUBLASLT_MATMUL_DESC_TRANSA / TRANSB to OP_N
        cublasOperation_t opN = CUBLAS_OP_N;
        cublasLtMatmulDescSetAttribute(opDesc, CUBLASLT_MATMUL_DESC_TRANSA, &opN, sizeof(opN));
        cublasLtMatmulDescSetAttribute(opDesc, CUBLASLT_MATMUL_DESC_TRANSB, &opN, sizeof(opN));

        // Row-major layouts: rows=m, cols=n, ld=leading dimension (= cols for row-major)
        // A2: (N*M) x K  -> rows=N*M, cols=K, ld=K
        if (cublasLtMatrixLayoutCreate(&layoutA, CUDA_R_32F, N*M, K, K) != CUBLAS_STATUS_SUCCESS) break;
        // B:  K x L      -> rows=K,   cols=L, ld=L
        if (cublasLtMatrixLayoutCreate(&layoutB, CUDA_R_32F, K,   L, L) != CUBLAS_STATUS_SUCCESS) break;
        // C:  (N*M) x L  -> rows=N*M, cols=L, ld=L
        if (cublasLtMatrixLayoutCreate(&layoutC, CUDA_R_32F, N*M, L, L) != CUBLAS_STATUS_SUCCESS) break;

        // Set row-major order on all layouts
        cublasLtOrder_t rowOrder = CUBLASLT_ORDER_ROW;
        cublasLtMatrixLayoutSetAttribute(layoutA, CUBLASLT_MATRIX_LAYOUT_ORDER, &rowOrder, sizeof(rowOrder));
        cublasLtMatrixLayoutSetAttribute(layoutB, CUBLASLT_MATRIX_LAYOUT_ORDER, &rowOrder, sizeof(rowOrder));
        cublasLtMatrixLayoutSetAttribute(layoutC, CUBLASLT_MATRIX_LAYOUT_ORDER, &rowOrder, sizeof(rowOrder));

        if (cublasLtMatmulPreferenceCreate(&pref) != CUBLAS_STATUS_SUCCESS) break;

        // Allocate workspace (16 MB)
        const size_t workspaceSize = 16 * 1024 * 1024;
        auto workspace = torch::empty({(int64_t)workspaceSize}, torch::TensorOptions().dtype(torch::kUInt8).device(A.device()));
        cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES, &workspaceSize, sizeof(workspaceSize));

        cublasLtMatmulHeuristicResult_t heurResult;
        int returnedAlgoCount = 0;
        cublasStatus_t heurStatus = cublasLtMatmulAlgoGetHeuristic(
            ltHandle, opDesc,
            layoutA, layoutB, layoutC, layoutC,
            pref, 1, &heurResult, &returnedAlgoCount);

        if (heurStatus != CUBLAS_STATUS_SUCCESS || returnedAlgoCount == 0) break;

        const float alpha = 1.0f, beta = 0.0f;
        cublasStatus_t st = cublasLtMatmul(
            ltHandle, opDesc,
            &alpha,
            A2.data_ptr<float>(), layoutA,
            B.data_ptr<float>(),  layoutB,
            &beta,
            C.data_ptr<float>(),  layoutC,
            C.data_ptr<float>(),  layoutC,
            &heurResult.algo,
            workspace.data_ptr(), workspaceSize,
            at::cuda::getCurrentCUDAStream());

        if (st != CUBLAS_STATUS_SUCCESS) break;
        use_lt = true;
    } while (false);

    if (layoutA) cublasLtMatrixLayoutDestroy(layoutA);
    if (layoutB) cublasLtMatrixLayoutDestroy(layoutB);
    if (layoutC) cublasLtMatrixLayoutDestroy(layoutC);
    if (opDesc)  cublasLtMatmulDescDestroy(opDesc);
    if (pref)    cublasLtMatmulPreferenceDestroy(pref);
    cublasLtDestroy(ltHandle);

    if (!use_lt) {
        // Fallback: plain cuBLAS SGEMM (column-major trick)
        cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
        cublasSetStream(handle, at::cuda::getCurrentCUDAStream());
        const float alpha = 1.0f, beta = 0.0f;
        cublasSgemm(
            handle,
            CUBLAS_OP_N, CUBLAS_OP_N,
            (int)L, (int)(N * M), (int)K,
            &alpha,
            B.data_ptr<float>(),  (int)L,
            A2.data_ptr<float>(), (int)K,
            &beta,
            C.data_ptr<float>(),  (int)L);
    }

    return C.view({N, M, L});
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Performs 3D tensor-matrix multiplication.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

