#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <ATen/cuda/CUDAContext.h>

torch::Tensor tensor_matmul3d_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "Inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat32 && B.dtype() == torch::kFloat32, "Inputs must be float32");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 2, "A must be 3D and B must be 2D");
    TORCH_CHECK(A.size(2) == B.size(0), "Dimension mismatch: A.shape[2] must equal B.shape[0]");

    A = A.contiguous();
    B = B.contiguous();

    const int64_t N = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    const int64_t L = B.size(1);

    auto C = torch::empty({N, M, L}, A.options());

    cublasHandle_t handle = at::cuda::getCurrentCUDABlasHandle();
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cublasSetStream(handle, stream);

    // cuBLAS is column-major. For row-major A(M,K) @ B(K,L) = C(M,L):
    // Interpret as column-major: A^T(K,M), B^T(L,K)
    // C^T(L,M) = B^T(L,K) * A^T(K,M)
    // cublasSgemm: C = alpha * op(A) * op(B) + beta * C
    // We want: C_col(L,M) = B_col(L,K) * A_col(K,M)
    // So: m=L, n=M, k=K, A_arg=B_ptr(lda=L), B_arg=A_ptr(ldb=K), C_arg=C_ptr(ldc=L)
    const float alpha = 1.0f;
    const float beta = 0.0f;

    const float* A_ptr = A.data_ptr<float>();
    const float* B_ptr = B.data_ptr<float>();
    float* C_ptr = C.data_ptr<float>();

    long long int strideA = (long long int)M * K;  // stride between batches of A
    long long int strideB = 0LL;                    // B is shared across batches
    long long int strideC = (long long int)M * L;  // stride between batches of C

    cublasStatus_t status = cublasSgemmStridedBatched(
        handle,
        CUBLAS_OP_N,  // op on B (column-major B is L x K, no transpose needed)
        CUBLAS_OP_N,  // op on A (column-major A is K x M, no transpose needed)
        (int)L,       // m: rows of op(B) and C
        (int)M,       // n: cols of op(A) and C
        (int)K,       // k: cols of op(B) and rows of op(A)
        &alpha,
        B_ptr,        // B matrix (shared)
        (int)L,       // ldb: leading dim of B in col-major = L
        strideB,      // stride for B (0 = broadcast)
        A_ptr,        // A matrix (batched)
        (int)K,       // lda: leading dim of A in col-major = K
        strideA,      // stride for A
        &beta,
        C_ptr,        // C matrix (batched output)
        (int)L,       // ldc: leading dim of C in col-major = L
        strideC,      // stride for C
        (int)N        // batch count
    );

    TORCH_CHECK(status == CUBLAS_STATUS_SUCCESS, "cublasSgemmStridedBatched failed with status ", (int)status);

    return C;
}
